/**
 * Downloads a regodrill release binary and installs it in the extension's storage. Node only, no VS Code API,
 * so it is unit-tested in plain Node.
 *
 * The version and the SHA-256 of each archive are fixed in regodrill-release.ts, generated by
 * scripts/update-regodrill.mjs after checking each archive's provenance attestation. An archive whose digest
 * differs is refused, whatever the server sends. Each version goes to its own directory,
 * `<storage>/<version>/regodrill[.exe]`, written to a temporary name first and renamed once complete.
 */
import { createHash } from 'crypto';
import { promises as fs } from 'fs';
import * as https from 'https';
import * as path from 'path';
import { extractFromTarGz, extractFromZip } from './archive';

export interface ReleaseAsset {
  /** File name of the archive in the GitHub release. */
  file: string;
  /** SHA-256 of the archive, hex. */
  sha256: string;
  /** Size of the archive in bytes, to tell the user before downloading. */
  size: number;
}

export interface RegodrillRelease {
  version: string;
  /** Archives by `${process.platform}-${process.arch}`. */
  assets: Record<string, ReleaseAsset>;
}

export const RELEASES_URL = 'https://github.com/adamaKomi/regodrill/releases';

/** The archive for a platform, or undefined when regodrill has no build for it. */
export function assetFor(
  release: RegodrillRelease,
  platform: string = process.platform,
  arch: string = process.arch
): ReleaseAsset | undefined {
  return release.assets[`${platform}-${arch}`];
}

export function binaryName(platform: string = process.platform): string {
  return platform === 'win32' ? 'regodrill.exe' : 'regodrill';
}

export function assetUrl(release: RegodrillRelease, asset: ReleaseAsset): string {
  return `${RELEASES_URL}/download/v${release.version}/${asset.file}`;
}

/** Where a version is installed. */
export function installedPath(
  storageDir: string,
  version: string,
  platform: string = process.platform
): string {
  return path.join(storageDir, version, binaryName(platform));
}

/** "7.2 MB" */
export function formatSize(bytes: number): string {
  return `${(bytes / 1_000_000).toFixed(1)} MB`;
}

export type Fetcher = (url: string) => Promise<Buffer>;

/**
 * Downloads a URL into memory, following redirects (GitHub serves release assets through a redirect to its
 * storage), over HTTPS only.
 */
export function fetchBuffer(
  url: string,
  options: { maxBytes?: number; maxRedirects?: number; timeoutMs?: number } = {}
): Promise<Buffer> {
  const { maxBytes = 64 * 1024 * 1024, maxRedirects = 5, timeoutMs = 120_000 } = options;
  return new Promise((resolve, reject) => {
    const target = new URL(url);
    if (target.protocol !== 'https:') {
      reject(new Error(`refusing to download over ${target.protocol} (${url})`));
      return;
    }
    const request = https.get(
      target,
      { headers: { 'User-Agent': 'rego-syntax-support' }, timeout: timeoutMs },
      (response) => {
        const status = response.statusCode ?? 0;
        if (status >= 300 && status < 400 && response.headers.location) {
          response.resume();
          if (maxRedirects <= 0) {
            reject(new Error(`too many redirects (${url})`));
            return;
          }
          const next = new URL(response.headers.location, target).toString();
          fetchBuffer(next, { maxBytes, maxRedirects: maxRedirects - 1, timeoutMs }).then(
            resolve,
            reject
          );
          return;
        }
        if (status !== 200) {
          response.resume();
          reject(new Error(`HTTP ${status} for ${url}`));
          return;
        }
        const chunks: Buffer[] = [];
        let received = 0;
        response.on('data', (chunk: Buffer) => {
          received += chunk.length;
          if (received > maxBytes) {
            request.destroy(new Error(`download larger than ${maxBytes} bytes (${url})`));
            return;
          }
          chunks.push(chunk);
        });
        response.on('end', () => resolve(Buffer.concat(chunks)));
        response.on('error', reject);
      }
    );
    request.on('timeout', () => request.destroy(new Error(`download timed out (${url})`)));
    request.on('error', reject);
  });
}

export function sha256(data: Buffer): string {
  return createHash('sha256').update(data).digest('hex');
}

/**
 * Downloads the release archive for this platform, checks its SHA-256, extracts the binary and installs it.
 * Returns the path of the binary.
 */
export async function installRegodrill(
  storageDir: string,
  release: RegodrillRelease,
  options: { platform?: string; arch?: string; fetch?: Fetcher } = {}
): Promise<string> {
  const platform = options.platform ?? process.platform;
  const arch = options.arch ?? process.arch;
  const asset = assetFor(release, platform, arch);
  if (!asset) {
    throw new Error(`regodrill ${release.version} has no build for ${platform}-${arch}`);
  }
  const fetch: Fetcher = options.fetch ?? ((url: string): Promise<Buffer> => fetchBuffer(url));
  const archive = await fetch(assetUrl(release, asset));
  const digest = sha256(archive);
  if (digest !== asset.sha256) {
    throw new Error(
      `${asset.file}: SHA-256 ${digest} does not match the expected ${asset.sha256}; nothing was installed`
    );
  }
  const name = binaryName(platform);
  const binary = asset.file.endsWith('.zip')
    ? extractFromZip(archive, name)
    : extractFromTarGz(archive, name);
  const target = installedPath(storageDir, release.version, platform);
  await fs.mkdir(path.dirname(target), { recursive: true });
  const partial = `${target}.partial-${process.pid}`;
  await fs.writeFile(partial, binary, { mode: 0o755 });
  await fs.rename(partial, target);
  return target;
}

/** The versions installed in the storage directory, oldest first (as sorted strings). */
export async function installedVersions(
  storageDir: string,
  platform: string = process.platform
): Promise<string[]> {
  let entries: string[];
  try {
    entries = await fs.readdir(storageDir);
  } catch {
    return [];
  }
  const versions: string[] = [];
  for (const entry of entries.sort()) {
    try {
      await fs.access(installedPath(storageDir, entry, platform));
      versions.push(entry);
    } catch {
      // not an installed version
    }
  }
  return versions;
}

/** Removes every installed version but `keep`. */
export async function removeOtherVersions(storageDir: string, keep: string): Promise<void> {
  let entries: string[];
  try {
    entries = await fs.readdir(storageDir);
  } catch {
    return;
  }
  for (const entry of entries) {
    if (entry !== keep) {
      await fs.rm(path.join(storageDir, entry), { recursive: true, force: true });
    }
  }
}

/**
 * Whether VS Code updates this extension automatically, from `extensions.autoUpdate`. Current VS Code has
 * `"on"` (default) and `"off"`; VS Code 1.85 had `true` (default), `"onlyEnabledExtensions"`,
 * `"onlySelectedExtensions"` and `false` (extensions.contribution.ts). With `"onlySelectedExtensions"`, the
 * extension cannot know whether the user selected it (the API does not expose it), so it asks instead.
 */
export function autoUpdateEnabled(value: unknown): boolean {
  return (
    value === undefined || value === true || value === 'on' || value === 'onlyEnabledExtensions'
  );
}
